bool installed() { return g_installed; }  // perf 2026-11-22

// The deferred commands so far, and how many calls drained the queue or fell back.
void stats(uint64_t& deferred, uint64_t& drains, uint64_t& fallbacks) {
    deferred = g_deferred.load(), drains = g_drains.load(), fallbacks = g_fallbacks.load();
}
